// Bundles the browser scripts in src/client/entries into one generated module
// the Worker serves (design note 0012).
//
//   node scripts/build-client.js          writes src/worker/client-scripts.generated.ts
//   node scripts/build-client.js --check  exits 1 if that file is out of date
//
// The generated file is committed, so deploys, tests and `wrangler dev` need
// no build step; CI runs --check so it can't go stale.

import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { build } from "esbuild";

/** Each entry in src/client/entries, and the constant its bundle is exported as. */
const ENTRIES = [
  { file: "countdown.ts", constant: "COUNTDOWN_JS" },
  { file: "story.ts", constant: "STORY_JS" },
  { file: "checkout.ts", constant: "CHECKOUT_JS" },
  { file: "vault.ts", constant: "VAULT_JS" },
  { file: "sound.ts", constant: "SOUND_JS" },
];

const root = new URL("../", import.meta.url);
const outFile = new URL("src/worker/client-scripts.generated.ts", root);

/** One entry, bundled into a single classic script: no imports left, nothing global. */
async function bundle(file) {
  const result = await build({
    entryPoints: [fileURLToPath(new URL(`src/client/entries/${file}`, root))],
    bundle: true,
    format: "iife",
    // Readable on purpose: the Fine Print says what runs in your browser, and
    // anyone can open these files and check.
    minify: false,
    target: ["es2020"],
    charset: "utf8",
    legalComments: "none",
    write: false,
    logLevel: "silent",
  });
  const [output] = result.outputFiles;
  if (output === undefined) throw new Error(`esbuild wrote nothing for ${file}`);
  return output.text;
}

/** A template literal holding `text` exactly. */
function templateLiteral(text) {
  return "`" + text.replaceAll("\\", "\\\\").replaceAll("`", "\\`").replaceAll("${", "\\${") + "`";
}

async function generate() {
  const parts = [
    "// Generated by scripts/build-client.js from src/client. Do not edit:",
    "// change the source and run `npm run build:client`.",
    "",
  ];
  for (const { file, constant } of ENTRIES) {
    parts.push(`/** Bundled from src/client/entries/${file}. */`);
    parts.push(`export const ${constant} = ${templateLiteral(await bundle(file))};`);
    parts.push("");
  }
  return parts.join("\n");
}

const generated = await generate();
if (process.argv.includes("--check")) {
  const current = await readFile(outFile, "utf8").catch(() => "");
  if (current !== generated) {
    console.error(
      "src/worker/client-scripts.generated.ts is out of date. Run `npm run build:client` and commit the result.",
    );
    process.exit(1);
  }
  console.log("Client scripts are up to date.");
} else {
  await writeFile(outFile, generated);
  console.log(`Wrote ${fileURLToPath(outFile)}`);
}
